#!/bin/bash
# grade.sh <artifact-dir> [--seed N] [--json out.json] [--toggle on|off|both]
#
# Runs every gate of the ci-test-matrix judge against the artifact's
# matrix.yaml + run_matrix.py and prints one JSON verdict.  Exits 0 only if
# every gate passes.
#
# <artifact-dir>: the directory holding matrix.yaml and run_matrix.py
# (typically examples/good, or a mutant generated by judge/mutants.py).
#
# The artifact is graded on a *copy* in a temp dir, so it cannot modify the
# judge tree; the self-test additionally checksums judge/ before and after.
set -euo pipefail
exec python3 "$(dirname "${BASH_SOURCE[0]}")/judge.py" "$@"
